insert into public.system_modules(module_key,name,description,sort_order) values('payroll','Payroll & HR','Employee salary profiles, shift planning, payroll, payslips and employment certificates.',80) on conflict(module_key) do update set name=excluded.name,description=excluded.description,sort_order=excluded.sort_order,is_active=true;
insert into public.system_package_modules(package_id,module_key) select 1,'payroll' where exists(select 1 from public.system_packages where id=1) on conflict do nothing;
create unique index if not exists restaurant_staff_tenant_id_uq on public.restaurant_staff(restaurant_id,id);
create table if not exists public.restaurant_employee_salary_profiles(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,employee_id uuid not null references public.restaurant_staff(id) on delete cascade,salary_basis text not null check(salary_basis in('monthly','daily')),salary_rate numeric(12,2) not null check(salary_rate>0),effective_from date not null default current_date,notes text not null default '',created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(restaurant_id,employee_id),foreign key(restaurant_id,employee_id) references public.restaurant_staff(restaurant_id,id) on delete cascade,check(length(notes)<=500));
create table if not exists public.restaurant_employee_salary_history(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,employee_id uuid not null references public.restaurant_staff(id) on delete cascade,salary_basis text not null check(salary_basis in('monthly','daily')),salary_rate numeric(12,2) not null check(salary_rate>0),effective_from date not null,superseded_at timestamptz not null default now(),changed_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),foreign key(restaurant_id,employee_id) references public.restaurant_staff(restaurant_id,id) on delete cascade);
create table if not exists public.restaurant_employee_shifts(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,employee_id uuid not null references public.restaurant_staff(id) on delete cascade,shift_date date not null,starts_at time not null,ends_at time not null,break_minutes integer not null default 0 check(break_minutes between 0 and 720),status text not null default 'scheduled' check(status in('scheduled','completed','absent','cancelled')),notes text not null default '',created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(restaurant_id,employee_id) references public.restaurant_staff(restaurant_id,id) on delete cascade,check(starts_at<>ends_at),check(length(notes)<=500));
create index if not exists restaurant_employee_shifts_date_idx on public.restaurant_employee_shifts(restaurant_id,shift_date,starts_at);
create table if not exists public.restaurant_payroll_runs(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,period_start date not null,period_end date not null,status text not null default 'draft' check(status in('draft','finalized','paid')),total_gross numeric(14,2) not null default 0 check(total_gross>=0),total_deductions numeric(14,2) not null default 0 check(total_deductions>=0),total_net numeric(14,2) not null default 0 check(total_net>=0),payment_date date,payment_method text not null default '',created_by uuid references auth.users(id) on delete set null,finalized_by uuid references auth.users(id) on delete set null,finalized_at timestamptz,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(period_end>=period_start),check(length(payment_method)<=80));
create table if not exists public.restaurant_payroll_items(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,payroll_run_id uuid not null references public.restaurant_payroll_runs(id) on delete cascade,employee_id uuid not null references public.restaurant_staff(id) on delete restrict,employee_name_snapshot text not null,employee_role_snapshot text not null,salary_basis_snapshot text not null check(salary_basis_snapshot in('monthly','daily')),salary_rate_snapshot numeric(12,2) not null check(salary_rate_snapshot>0),days_worked numeric(6,2) not null default 0 check(days_worked>=0),base_earnings numeric(12,2) not null check(base_earnings>=0),additional_earnings numeric(12,2) not null default 0 check(additional_earnings>=0),deductions numeric(12,2) not null default 0 check(deductions>=0),gross_pay numeric(12,2) not null check(gross_pay>=0),net_pay numeric(12,2) not null check(net_pay>=0),adjustment_note text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(payroll_run_id,employee_id),foreign key(restaurant_id,employee_id) references public.restaurant_staff(restaurant_id,id) on delete restrict,check(net_pay=gross_pay-deductions));
create table if not exists public.restaurant_employee_documents(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,employee_id uuid not null references public.restaurant_staff(id) on delete cascade,payroll_run_id uuid references public.restaurant_payroll_runs(id) on delete set null,document_type text not null check(document_type in('payslip','certificate_of_employment')),issued_at timestamptz not null default now(),issued_by uuid references auth.users(id) on delete set null,metadata jsonb not null default '{}'::jsonb,foreign key(restaurant_id,employee_id) references public.restaurant_staff(restaurant_id,id) on delete cascade);
create or replace function public.restaurant_record_salary_profile_history() returns trigger language plpgsql security definer set search_path='' as $$ begin if old.salary_basis is distinct from new.salary_basis or old.salary_rate is distinct from new.salary_rate or old.effective_from is distinct from new.effective_from then insert into public.restaurant_employee_salary_history(restaurant_id,employee_id,salary_basis,salary_rate,effective_from,changed_by) values(old.restaurant_id,old.employee_id,old.salary_basis,old.salary_rate,old.effective_from,auth.uid()); end if; return new; end; $$;
drop trigger if exists restaurant_salary_history_trigger on public.restaurant_employee_salary_profiles;
create trigger restaurant_salary_history_trigger before update on public.restaurant_employee_salary_profiles for each row execute function public.restaurant_record_salary_profile_history();
create or replace function public.restaurant_guard_finalized_payroll_item() returns trigger language plpgsql security invoker set search_path='' as $$ declare rid uuid; st text; begin rid:=case when tg_op='DELETE' then old.payroll_run_id else new.payroll_run_id end; select status into st from public.restaurant_payroll_runs where id=rid; if st in('finalized','paid') then raise exception 'Finalized payroll items cannot be changed.'; end if; if tg_op='DELETE' then return old; end if; return new; end; $$;
drop trigger if exists restaurant_payroll_item_guard on public.restaurant_payroll_items;
create trigger restaurant_payroll_item_guard before insert or update or delete on public.restaurant_payroll_items for each row execute function public.restaurant_guard_finalized_payroll_item();
alter table public.restaurant_employee_salary_profiles enable row level security; alter table public.restaurant_employee_salary_history enable row level security; alter table public.restaurant_employee_shifts enable row level security; alter table public.restaurant_payroll_runs enable row level security; alter table public.restaurant_payroll_items enable row level security; alter table public.restaurant_employee_documents enable row level security;
grant select,insert,update,delete on public.restaurant_employee_salary_profiles to authenticated; grant select on public.restaurant_employee_salary_history to authenticated; grant select,insert,update,delete on public.restaurant_employee_shifts to authenticated; grant select,insert,update,delete on public.restaurant_payroll_runs to authenticated; grant select,insert,update,delete on public.restaurant_payroll_items to authenticated; grant select,insert on public.restaurant_employee_documents to authenticated; grant execute on function public.is_restaurant_owner(uuid) to authenticated;
drop policy if exists "Owner salary profiles" on public.restaurant_employee_salary_profiles; create policy "Owner salary profiles" on public.restaurant_employee_salary_profiles for all to authenticated using(public.is_restaurant_owner(restaurant_id)) with check(public.is_restaurant_owner(restaurant_id));
drop policy if exists "Owner salary history" on public.restaurant_employee_salary_history; create policy "Owner salary history" on public.restaurant_employee_salary_history for select to authenticated using(public.is_restaurant_owner(restaurant_id));
drop policy if exists "Owner employee shifts" on public.restaurant_employee_shifts; create policy "Owner employee shifts" on public.restaurant_employee_shifts for all to authenticated using(public.is_restaurant_owner(restaurant_id)) with check(public.is_restaurant_owner(restaurant_id));
drop policy if exists "Owner payroll runs" on public.restaurant_payroll_runs; create policy "Owner payroll runs" on public.restaurant_payroll_runs for all to authenticated using(public.is_restaurant_owner(restaurant_id)) with check(public.is_restaurant_owner(restaurant_id));
drop policy if exists "Owner payroll items" on public.restaurant_payroll_items; create policy "Owner payroll items" on public.restaurant_payroll_items for all to authenticated using(public.is_restaurant_owner(restaurant_id)) with check(public.is_restaurant_owner(restaurant_id));
drop policy if exists "Owner employee documents" on public.restaurant_employee_documents; create policy "Owner employee documents" on public.restaurant_employee_documents for all to authenticated using(public.is_restaurant_owner(restaurant_id)) with check(public.is_restaurant_owner(restaurant_id));

create or replace function public.restaurant_guard_payroll_run_state() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='DELETE' then
  if old.status<>'draft' then raise exception 'Finalized payroll runs cannot be deleted.'; end if;
  return old;
 end if;
 if old.status='draft' and new.status in('draft','finalized') then return new; end if;
 if old.status='finalized' and new.status='paid' then return new; end if;
 raise exception 'Payroll run status cannot be changed from % to %.',old.status,new.status;
end; $$;
drop trigger if exists restaurant_payroll_run_state_guard on public.restaurant_payroll_runs;
create trigger restaurant_payroll_run_state_guard before update or delete on public.restaurant_payroll_runs for each row execute function public.restaurant_guard_payroll_run_state();
